# ═══════════════════════════════════════
#  场景：查询明天上海的天气
# ═══════════════════════════════════════

# 1. 用户提问
user_input = "明天上海天气怎么样？"

# 2. 定义可用的工具
tools = [
    {
        "name": "get_weather",
        "description": "获取指定城市的天气信息",
        "parameters": {
            "city": "城市名称",
            "date": "日期（如：明天、后天、2025-12-15）"
        }
    }
]

# 3. LLM分析并决定调用工具
response = llm.chat(
    message=user_input,
    tools=tools  # 告诉LLM有哪些工具可用
)

# 4. LLM返回：我需要调用get_weather
response = {
    "tool_call": {
        "name": "get_weather",
        "arguments": {
            "city": "上海",
            "date": "明天"
        }
    }
}

# 5. 执行实际的函数调用
def get_weather(city, date):
    # 这里调用真实的天气API
    api_result = call_weather_api(city, date)
    return api_result

result = get_weather("上海", "明天")
# result = {
#     "city": "上海",
#     "date": "2026-01-16",
#     "temperature": "15-22℃",
#     "weather": "晴",
#     "wind": "北风3级"
# }

# 6. 把函数结果返回给LLM
final_answer = llm.chat(
    message=user_input,
    tool_result=result
)

# 7. LLM生成最终回答
print(final_answer)
# "明天上海晴天，气温15-22℃，北风3级，
#  是个适合出行的好天气！建议穿薄外套。"

